// M12 Android extras, re-applied every time android/ is generated by `expo prebuild` (android/ is not committed):
// share-to-app filter, launcher icon aliases + their resources, app shortcuts. The native module itself lives in
// modules/taskly-android (autolinked); widgets come from react-native-android-widget (declared in app.json).
const fs = require('fs');
const path = require('path');
const { withAndroidColors, withAndroidManifest, withDangerousMod, AndroidConfig } = require('expo/config-plugins');
const { ICON_BACKGROUNDS, ICON_NAMES, adaptiveIconXml, applyTasklyManifest, colorName } = require('./tasklyAndroidManifest');

const CUSTOM_ICONS = ICON_NAMES.filter((name) => name !== 'default');

function withManifest(config) {
  return withAndroidManifest(config, (cfg) => {
    cfg.modResults = applyTasklyManifest(cfg.modResults);
    return cfg;
  });
}

function withIconColors(config) {
  return withAndroidColors(config, (cfg) => {
    for (const name of CUSTOM_ICONS) {
      cfg.modResults = AndroidConfig.Colors.assignColorValue(cfg.modResults, {
        name: colorName(name),
        value: ICON_BACKGROUNDS[name],
      });
    }
    return cfg;
  });
}

function withIconResources(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const dir = path.join(cfg.modRequest.platformProjectRoot, 'app', 'src', 'main', 'res', 'mipmap-anydpi-v26');
      await fs.promises.mkdir(dir, { recursive: true });
      for (const name of CUSTOM_ICONS) {
        await fs.promises.writeFile(path.join(dir, `ic_launcher_${name}.xml`), adaptiveIconXml(name));
      }
      return cfg;
    },
  ]);
}

module.exports = function withTasklyAndroid(config) {
  return withIconResources(withIconColors(withManifest(config)));
};
